---@alias paypal.checkout_orders_v2.ServerCallbackRequestPurchaseUnitsItemShippingType "SHIPPING"|"PICKUP_IN_PERSON"|"PICKUP_IN_STORE"|"PICKUP_FROM_PERSON"

